import { Injectable } from '@nestjs/common';

@Injectable()
export class AppService {
  getHello(): string {
    return 'Hello World!';
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Attendance } from '../attendance.entity';
import {
  CheckInAttendanceDto,
  CheckOutAttendanceDto,
} from '../dtos/attendance.dto';
import { Employee } from 'src/employees/employee.entity';
import { Estate } from 'src/estates/estate.entity';
import { Role } from 'src/auth/enums/role.enum';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class AttendanceService {
  constructor(
    @InjectRepository(Attendance)
    private readonly attendanceRepo: Repository<Attendance>,

    @InjectRepository(Employee)
    private readonly employeesRepo: Repository<Employee>,

    @InjectRepository(Estate)
    private readonly estatesRepo: Repository<Estate>,
  ) {}

  public async checkIn(dto: CheckInAttendanceDto, user?: ActiveUserData) {
    const [worker, estate] = await Promise.all([
      this.employeesRepo.findOne({
        where: { id: dto.workerId },
        relations: { owner: true },
      }),
      this.estatesRepo.findOne({
        where: { id: dto.estateId },
        relations: { owner: true },
      }),
    ]);

    if (!worker) throw new NotFoundException('Worker not found');
    if (!estate) throw new NotFoundException('Estate not found');

    if (user && user.role === Role.OWNER) {
      if (estate.owner?.id !== user.ownerId) {
        throw new ForbiddenException(
          'You can only record attendance for your own estates',
        );
      }
      if (worker.owner && worker.owner.id !== user.ownerId) {
        throw new ForbiddenException(
          'You cannot record attendance for another owner’s worker',
        );
      }
    }

    const date = dto.date ? new Date(dto.date) : new Date();
    const checkIn = dto.checkIn ? new Date(dto.checkIn) : new Date();

    const attendance = this.attendanceRepo.create({
      worker,
      estate,
      date,
      checkIn,
      status: dto.status ?? 'present',
    });

    return this.attendanceRepo.save(attendance);
  }

  public async checkOut(
    id: string,
    dto: CheckOutAttendanceDto,
    user?: ActiveUserData,
  ) {
    const record = await this.attendanceRepo.findOne({
      where: { id },
      relations: { estate: { owner: true } },
    });
    if (!record) {
      throw new NotFoundException(`Attendance record with ID ${id} not found`);
    }

    if (
      user &&
      user.role === Role.OWNER &&
      record.estate?.owner?.id !== user.ownerId
    ) {
      throw new ForbiddenException(
        'You do not have access to this attendance record',
      );
    }

    record.checkOut = dto.checkOut ? new Date(dto.checkOut) : new Date();
    if (dto.status) {
      record.status = dto.status;
    }

    return this.attendanceRepo.save(record);
  }

  public async findAll(
    filter?: {
      workerId?: string;
      estateId?: string;
      date?: string;
    },
    user?: ActiveUserData,
  ) {
    const query = this.attendanceRepo
      .createQueryBuilder('attendance')
      .leftJoinAndSelect('attendance.worker', 'worker')
      .leftJoinAndSelect('attendance.estate', 'estate')
      .orderBy('attendance.checkIn', 'DESC');

    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      query.andWhere('estate.owner_id = :ownerId', { ownerId: user.ownerId });
    }

    if (filter?.workerId) {
      query.andWhere('attendance.worker_id = :workerId', {
        workerId: filter.workerId,
      });
    }
    if (filter?.estateId) {
      query.andWhere('attendance.estate_id = :estateId', {
        estateId: filter.estateId,
      });
    }
    if (filter?.date) {
      query.andWhere('attendance.date = :date', { date: filter.date });
    }

    return query.getMany();
  }
}

import {
  ConflictException,
  Injectable,
  NotFoundException,
  UnauthorizedException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { JwtService } from '@nestjs/jwt';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from '../entities/users.entity';
import { Role } from '../enums/role.enum';
import { UserStatus } from '../enums/user-status.enum';
import { RegisterDto } from '../dtos/register.dto';
import { LoginDto } from '../dtos/login.dto';
import { RefreshTokenDto } from '../dtos/refresh-token.dto';
import { BcryptService } from './bcrypt.service';
import { ActiveUserData } from '../interfaces/active-user-data.interface';
import { Owner } from 'src/owners/owner.entity';
import { OwnerStatus } from 'src/owners/enums/owner-status.enum';
import type { SignOptions } from 'jsonwebtoken';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User)
    private readonly usersRepository: Repository<User>,

    @InjectRepository(Owner)
    private readonly ownersRepository: Repository<Owner>,

    private readonly bcryptService: BcryptService,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  public async register(registerDto: RegisterDto) {
    const normalizedEmail = registerDto.email.trim().toLowerCase();

    const existingUser = await this.usersRepository.findOne({
      where: { email: normalizedEmail },
    });

    if (existingUser) {
      throw new ConflictException('A user with this email already exists');
    }

    const role = registerDto.role ?? Role.OWNER;
    const passwordHash = await this.bcryptService.hashPassword(
      registerDto.password,
    );

    let linkedOwner: Owner | null = null;

    if (role === Role.OWNER) {
      linkedOwner = await this.ownersRepository.findOne({
        where: { email: normalizedEmail },
      });

      if (!linkedOwner) {
        const newOwner = this.ownersRepository.create({
          name: registerDto.name ?? normalizedEmail.split('@')[0],
          email: normalizedEmail,
          phone: registerDto.phone ?? '',
          address: registerDto.address ?? '',
          status: OwnerStatus.ACTIVE,
        });
        linkedOwner = await this.ownersRepository.save(newOwner);
      }
    }

    const newUser = this.usersRepository.create({
      email: normalizedEmail,
      passwordHash,
      role,
      status: UserStatus.ACTIVE,
      owner: linkedOwner,
    });

    const savedUser = await this.usersRepository.save(newUser);
    const tokens = await this.generateTokens(savedUser);

    return {
      message: 'User registered successfully',
      ...tokens,
      user: this.sanitizeUser(savedUser),
    };
  }

  public async login(loginDto: LoginDto) {
    const normalizedEmail = loginDto.email.trim().toLowerCase();

    const user = await this.usersRepository.findOne({
      where: { email: normalizedEmail },
      relations: { owner: true },
    });

    if (!user) {
      throw new UnauthorizedException('Invalid email or password');
    }

    if (user.status !== UserStatus.ACTIVE) {
      throw new UnauthorizedException(
        `Account is currently ${user.status}. Please contact support.`,
      );
    }

    const isPasswordValid = await this.bcryptService.comparePassword(
      loginDto.password,
      user.passwordHash,
    );

    if (!isPasswordValid) {
      throw new UnauthorizedException('Invalid email or password');
    }

    if (user.role === Role.OWNER && !user.owner) {
      let linkedOwner = await this.ownersRepository.findOne({
        where: { email: normalizedEmail },
      });
      if (!linkedOwner) {
        linkedOwner = await this.ownersRepository.save(
          this.ownersRepository.create({
            name: normalizedEmail.split('@')[0],
            email: normalizedEmail,
            status: OwnerStatus.ACTIVE,
          }),
        );
      }
      user.owner = linkedOwner;
    }

    user.lastLogin = new Date();
    await this.usersRepository.save(user);

    const tokens = await this.generateTokens(user);

    return {
      message: 'Login successful',
      ...tokens,
      user: this.sanitizeUser(user),
    };
  }

  public async refreshToken(refreshTokenDto: RefreshTokenDto) {
    const jwtSecret =
      this.configService.get<string>('JWT_REFRESH_SECRET') ??
      this.configService.get<string>('JWT_SECRET') ??
      'estate360-jwt-secret-key-super-safe';

    try {
      const payload = await this.jwtService.verifyAsync<ActiveUserData>(
        refreshTokenDto.refreshToken,
        { secret: jwtSecret },
      );

      const user = await this.usersRepository.findOne({
        where: { id: payload.sub },
        relations: { owner: true },
      });

      if (!user || user.status !== UserStatus.ACTIVE) {
        throw new UnauthorizedException(
          'User not found or account is no longer active',
        );
      }

      const tokens = await this.generateTokens(user);

      return {
        message: 'Tokens refreshed successfully',
        ...tokens,
      };
    } catch {
      throw new UnauthorizedException('Invalid or expired refresh token');
    }
  }

  public async getProfile(userId: string) {
    const user = await this.usersRepository.findOne({
      where: { id: userId },
      relations: { owner: true },
    });

    if (!user) {
      throw new NotFoundException('User not found');
    }

    return this.sanitizeUser(user);
  }

  public async findUserByEmail(email: string): Promise<User | null> {
    return this.usersRepository.findOne({
      where: { email: email.trim().toLowerCase() },
      relations: { owner: true },
    });
  }

  public async findUserById(id: string): Promise<User | null> {
    return this.usersRepository.findOne({
      where: { id },
      relations: { owner: true },
    });
  }

  private async generateTokens(user: User) {
    const payload: ActiveUserData = {
      sub: user.id,
      email: user.email,
      role: user.role,
      ownerId: user.owner ? user.owner.id : null,
    };

    const jwtSecret =
      this.configService.get<string>('JWT_SECRET') ??
      'estate360-jwt-secret-key-super-safe';

    const jwtRefreshSecret =
      this.configService.get<string>('JWT_REFRESH_SECRET') ?? jwtSecret;

    const accessTokenExpiresIn = (this.configService.get<string>(
      'JWT_EXPIRES_IN',
    ) ?? '1d') as SignOptions['expiresIn'];

    const refreshTokenExpiresIn = (this.configService.get<string>(
      'JWT_REFRESH_EXPIRES_IN',
    ) ?? '7d') as SignOptions['expiresIn'];

    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(payload, {
        secret: jwtSecret,
        expiresIn: accessTokenExpiresIn,
      }),
      this.jwtService.signAsync(payload, {
        secret: jwtRefreshSecret,
        expiresIn: refreshTokenExpiresIn,
      }),
    ]);

    return {
      accessToken,
      refreshToken,
    };
  }

  private sanitizeUser(user: User) {
    return {
      id: user.id,
      email: user.email,
      role: user.role,
      status: user.status,
      lastLogin: user.lastLogin,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
      owner: user.owner
        ? {
            id: user.owner.id,
            name: user.owner.name,
            contactEmail: user.owner.contactEmail,
            phone: user.owner.phone,
            address: user.owner.address,
            status: user.owner.status,
          }
        : null,
    };
  }
}

import { Injectable } from '@nestjs/common';
import * as bcrypt from 'bcryptjs';

@Injectable()
export class BcryptService {
  public async hashPassword(password: string): Promise<string> {
    const salt = await bcrypt.genSalt(10);
    return bcrypt.hash(password, salt);
  }

  public async comparePassword(
    password: string,
    hash: string,
  ): Promise<boolean> {
    return bcrypt.compare(password, hash);
  }
}

import {
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { CreateCropDto } from '../dtos/createCropDto';
import { UpdateCropDto } from '../dtos/updateCropDto';
import { InjectRepository } from '@nestjs/typeorm';
import { Crop } from '../crop.entity';
import { Repository } from 'typeorm';

@Injectable()
export class CropsService {
  constructor(
    @InjectRepository(Crop)
    private readonly cropRepository: Repository<Crop>,
  ) {}

  public async createCrop(createCropDto: CreateCropDto) {
    const existing = await this.cropRepository.findOne({
      where: [{ name: createCropDto.name }, { code: createCropDto.code }],
    });

    if (existing) {
      throw new ConflictException(
        'A crop with this name or code already exists',
      );
    }

    const crop = this.cropRepository.create(createCropDto);
    return this.cropRepository.save(crop);
  }

  public async findAllCrops() {
    return this.cropRepository.find();
  }

  public async findOneCrop(id: string) {
    const crop = await this.cropRepository.findOne({ where: { id } });
    if (!crop) {
      throw new NotFoundException(`Crop with ID ${id} not found`);
    }
    return crop;
  }

  public async updateCrop(id: string, updateCropDto: UpdateCropDto) {
    const crop = await this.findOneCrop(id);
    Object.assign(crop, updateCropDto);
    return this.cropRepository.save(crop);
  }

  public async deleteCrop(id: string) {
    const crop = await this.findOneCrop(id);
    await this.cropRepository.remove(crop);
    return { message: 'Crop deleted successfully' };
  }
}

import {
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Employee } from '../employee.entity';
import { Repository } from 'typeorm';
import { CreateEmployeeDto } from '../dtos/createEmployeeDto';
import { PatchEmployeeDto } from '../dtos/patchEmployeeDto';
import { EmployeeStatus } from '../enums/employee-status.enum';
import { Owner } from 'src/owners/owner.entity';
import { Estate } from 'src/estates/estate.entity';
import { EstateAssignment } from 'src/assignments/entities/estate-assignment.entity';
import { Role as AssignmentRole } from 'src/assignments/enums/role.enum';
import { Role } from 'src/auth/enums/role.enum';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class EmployeesService {
  constructor(
    @InjectRepository(Employee)
    private readonly employeesRepository: Repository<Employee>,

    @InjectRepository(Owner)
    private readonly ownersRepository: Repository<Owner>,

    @InjectRepository(Estate)
    private readonly estatesRepository: Repository<Estate>,

    @InjectRepository(EstateAssignment)
    private readonly estateAssignmentsRepository: Repository<EstateAssignment>,
  ) {}

  public async createEmployee(
    createEmployeeDto: CreateEmployeeDto,
    user?: ActiveUserData,
  ) {
    const normalizedCode = createEmployeeDto.employeeCode.trim().toUpperCase();
    const normalizedNic = createEmployeeDto.nic.trim().toUpperCase();

    const existing = await this.employeesRepository.findOne({
      where: [
        { employeeCode: normalizedCode },
        { nic: normalizedNic },
      ],
    });

    if (existing) {
      if (existing.employeeCode === normalizedCode) {
        throw new ConflictException(
          `Employee code "${normalizedCode}" is already in use`,
        );
      }
      throw new ConflictException(
        `An employee with NIC "${normalizedNic}" already exists`,
      );
    }

    let ownerId = createEmployeeDto.ownerId;

    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      if (ownerId && ownerId !== user.ownerId) {
        throw new ForbiddenException(
          'You can only create employees under your own owner account',
        );
      }
      ownerId = user.ownerId;
    }

    let owner: Owner | null = null;
    if (ownerId) {
      owner = await this.ownersRepository.findOne({ where: { id: ownerId } });
      if (!owner) {
        throw new NotFoundException('Owner not found');
      }
    }

    const normalizedRole =
      createEmployeeDto.role?.toLowerCase() === 'supervisor'
        ? 'supervisor'
        : 'worker';

    const employee = this.employeesRepository.create({
      ...createEmployeeDto,
      employeeCode: normalizedCode,
      nic: normalizedNic,
      role: normalizedRole,
      status: createEmployeeDto.status ?? EmployeeStatus.ACTIVE,
      owner,
      dateOfBirth: createEmployeeDto.dateOfBirth ?? createEmployeeDto.dob,
    });

    const savedEmployee = await this.employeesRepository.save(employee);

    if (createEmployeeDto.estateId) {
      const estate = await this.estatesRepository.findOne({
        where: { id: createEmployeeDto.estateId },
        relations: { owner: true },
      });

      if (!estate) {
        throw new NotFoundException('Assigned estate not found');
      }

      if (
        user &&
        user.role === Role.OWNER &&
        estate.owner?.id !== user.ownerId
      ) {
        throw new ForbiddenException(
          'You can only assign employees to your own estates',
        );
      }

      const assignmentRole =
        normalizedRole === 'supervisor'
          ? AssignmentRole.SUPERVISOR
          : AssignmentRole.WORKER;

      const assignment = this.estateAssignmentsRepository.create({
        estate,
        employee: savedEmployee,
        role: assignmentRole,
        startDate: createEmployeeDto.dateJoined ?? new Date(),
      });

      await this.estateAssignmentsRepository.save(assignment);
    }

    return this.findOneEmployee(savedEmployee.id, user);
  }

  public async updateEmployee(
    id: string,
    patchEmployeeDto: PatchEmployeeDto,
    user?: ActiveUserData,
  ) {
    const employee = await this.findOneEmployee(id, user);

    if (patchEmployeeDto.employeeCode) {
      employee.employeeCode = patchEmployeeDto.employeeCode.trim().toUpperCase();
    }
    if (patchEmployeeDto.nic) {
      employee.nic = patchEmployeeDto.nic.trim().toUpperCase();
    }
    if (patchEmployeeDto.firstName) {
      employee.firstName = patchEmployeeDto.firstName.trim();
    }
    if (patchEmployeeDto.lastName !== undefined) {
      employee.lastName = patchEmployeeDto.lastName?.trim() || undefined;
    }
    if (patchEmployeeDto.phone !== undefined) {
      employee.phone = patchEmployeeDto.phone?.trim() || undefined;
    }
    if (patchEmployeeDto.address !== undefined) {
      employee.address = patchEmployeeDto.address?.trim() || undefined;
    }
    if (patchEmployeeDto.role !== undefined) {
      employee.role =
        patchEmployeeDto.role.toLowerCase() === 'supervisor'
          ? 'supervisor'
          : 'worker';
    }
    if (patchEmployeeDto.status !== undefined) {
      employee.status = patchEmployeeDto.status;
    }
    if (
      patchEmployeeDto.dateOfBirth !== undefined ||
      patchEmployeeDto.dob !== undefined
    ) {
      employee.dateOfBirth =
        patchEmployeeDto.dateOfBirth ?? patchEmployeeDto.dob;
    }
    if (patchEmployeeDto.dateJoined !== undefined) {
      employee.dateJoined = patchEmployeeDto.dateJoined;
    }

    const saved = await this.employeesRepository.save(employee);

    if (patchEmployeeDto.estateId) {
      const estate = await this.estatesRepository.findOne({
        where: { id: patchEmployeeDto.estateId },
        relations: { owner: true },
      });

      if (!estate) {
        throw new NotFoundException('Estate not found');
      }

      if (
        user &&
        user.role === Role.OWNER &&
        estate.owner?.id !== user.ownerId
      ) {
        throw new ForbiddenException(
          'You can only assign employees to your own estates',
        );
      }

      // Check if an existing estate assignment exists
      let existingAssignment = await this.estateAssignmentsRepository.findOne({
        where: { employee: { id: saved.id }, estate: { id: estate.id } },
      });

      const assignmentRole =
        (saved.role || 'worker') === 'supervisor'
          ? AssignmentRole.SUPERVISOR
          : AssignmentRole.WORKER;

      if (existingAssignment) {
        existingAssignment.role = assignmentRole;
        await this.estateAssignmentsRepository.save(existingAssignment);
      } else {
        const newAssignment = this.estateAssignmentsRepository.create({
          estate,
          employee: saved,
          role: assignmentRole,
          startDate: saved.dateJoined ?? new Date(),
        });
        await this.estateAssignmentsRepository.save(newAssignment);
      }
    }

    return this.findOneEmployee(saved.id, user);
  }

  public async findAllEmployees(user?: ActiveUserData) {
    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }

      return this.employeesRepository
        .createQueryBuilder('employee')
        .leftJoinAndSelect('employee.owner', 'owner')
        .leftJoinAndSelect('employee.estateAssignments', 'ea')
        .leftJoinAndSelect('ea.estate', 'eaEstate')
        .leftJoinAndSelect('employee.workerAssignments', 'wa')
        .leftJoinAndSelect('wa.estate', 'waEstate')
        .where(
          '(employee.owner_id = :ownerId OR eaEstate.owner_id = :ownerId OR waEstate.owner_id = :ownerId)',
          { ownerId: user.ownerId },
        )
        .orderBy('employee.createdAt', 'DESC')
        .getMany();
    }

    return this.employeesRepository.find({
      relations: {
        owner: true,
        estateAssignments: { estate: true },
        workerAssignments: { estate: true },
      },
      order: { createdAt: 'DESC' },
    });
  }

  public async findOneEmployee(id: string, user?: ActiveUserData) {
    const employee = await this.employeesRepository.findOne({
      where: { id },
      relations: {
        owner: true,
        estateAssignments: { estate: { owner: true } },
        workerAssignments: { estate: { owner: true } },
      },
    });
    if (!employee) throw new NotFoundException('employee not found');

    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }

      const isDirectOwner = employee.owner?.id === user.ownerId;
      const isAssignedToOwnerEstate =
        (employee.estateAssignments ?? []).some(
          (ea) => ea.estate?.owner?.id === user.ownerId,
        ) ||
        (employee.workerAssignments ?? []).some(
          (wa) => wa.estate?.owner?.id === user.ownerId,
        );

      if (!isDirectOwner && !isAssignedToOwnerEstate) {
        throw new ForbiddenException('You do not have access to this employee');
      }
    }

    return employee;
  }

  public async deleteEmployee(id: string, user?: ActiveUserData) {
    const employee = await this.findOneEmployee(id, user);

    try {
      await this.employeesRepository.query(
        'DELETE FROM "estate_assignment" WHERE "employee_id" = $1',
        [employee.id],
      );
      await this.employeesRepository.query(
        'DELETE FROM "worker_assignment" WHERE "worker_id" = $1 OR "supervisor_id" = $1',
        [employee.id],
      );
    } catch {
      // Safe catch
    }

    await this.employeesRepository.remove(employee);

    return { message: 'employee deleted successfully' };
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
  OnModuleInit,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreateEstateAssignmentDto } from '../dtos/estate-assignment/createEstateAssignmentDto';
import { Estate } from 'src/estates/estate.entity';
import { Employee } from 'src/employees/employee.entity';
import { EstateAssignment } from '../entities/estate-assignment.entity';
import { UpdateEstateAssignmentDto } from '../dtos/estate-assignment/updateEstateAssignmentDto';
import { Role as AuthRole } from 'src/auth/enums/role.enum';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class EstateAssignmentService implements OnModuleInit {
  constructor(
    @InjectRepository(EstateAssignment)
    private readonly estateAssignementRepository: Repository<EstateAssignment>,

    @InjectRepository(Estate)
    private readonly estateRepository: Repository<Estate>,

    @InjectRepository(Employee)
    private readonly employeesRepository: Repository<Employee>,
  ) {}

  async onModuleInit() {
    try {
      await this.estateAssignementRepository.query(
        `UPDATE "estate_assignment" SET "role" = 'supervisor' WHERE "role" IS NULL`,
      );
    } catch {
      // Safe catch if database/table not ready yet
    }
  }

  public async createAssignment(
    createEstateAssignmentDto: CreateEstateAssignmentDto,
    user?: ActiveUserData,
  ) {
    const estate = await this.estateRepository.findOne({
      where: { id: createEstateAssignmentDto.estateId },
      relations: { owner: true },
    });

    if (!estate) throw new NotFoundException('estate not found');

    if (
      user &&
      user.role === AuthRole.OWNER &&
      estate.owner?.id !== user.ownerId
    ) {
      throw new ForbiddenException(
        'You can only assign employees to your own estates',
      );
    }

    const employee = await this.employeesRepository.findOne({
      where: { id: createEstateAssignmentDto.employeeId },
      relations: { owner: true },
    });

    if (!employee) throw new NotFoundException('employee not found');

    if (
      user &&
      user.role === AuthRole.OWNER &&
      employee.owner &&
      employee.owner.id !== user.ownerId
    ) {
      throw new ForbiddenException(
        'You cannot assign an employee belonging to another owner',
      );
    }

    const assignment = this.estateAssignementRepository.create({
      startDate: createEstateAssignmentDto.startDate,
      endDate: createEstateAssignmentDto.endDate,
      estate,
      employee,
      role: createEstateAssignmentDto.role,
    });

    return this.estateAssignementRepository.save(assignment);
  }

  public async updateAssignment(
    id: string,
    updateEstateAssignmentDto: UpdateEstateAssignmentDto,
    user?: ActiveUserData,
  ) {
    const assignment = await this.findAssignmentById(id, user);

    if (updateEstateAssignmentDto.estateId) {
      const estate = await this.estateRepository.findOne({
        where: { id: updateEstateAssignmentDto.estateId },
        relations: { owner: true },
      });

      if (!estate) throw new NotFoundException('estate not found');

      if (
        user &&
        user.role === AuthRole.OWNER &&
        estate.owner?.id !== user.ownerId
      ) {
        throw new ForbiddenException(
          'You can only assign employees to your own estates',
        );
      }

      assignment.estate = estate;
    }

    if (updateEstateAssignmentDto.employeeId) {
      const employee = await this.employeesRepository.findOne({
        where: { id: updateEstateAssignmentDto.employeeId },
        relations: { owner: true },
      });

      if (!employee) throw new NotFoundException('employee not found');

      if (
        user &&
        user.role === AuthRole.OWNER &&
        employee.owner &&
        employee.owner.id !== user.ownerId
      ) {
        throw new ForbiddenException(
          'You cannot assign an employee belonging to another owner',
        );
      }

      assignment.employee = employee;
    }

    if (updateEstateAssignmentDto.role !== undefined) {
      assignment.role = updateEstateAssignmentDto.role;
    }

    if (updateEstateAssignmentDto.endDate !== undefined) {
      assignment.endDate = updateEstateAssignmentDto.endDate;
    }

    if (updateEstateAssignmentDto.startDate !== undefined) {
      assignment.startDate = updateEstateAssignmentDto.startDate;
    }

    return this.estateAssignementRepository.save(assignment);
  }

  public async findAllAssignments(user?: ActiveUserData) {
    if (user && user.role === AuthRole.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      return this.estateAssignementRepository.find({
        where: { estate: { owner: { id: user.ownerId } } },
        relations: { estate: true, employee: true },
      });
    }

    return this.estateAssignementRepository.find({
      relations: { estate: true, employee: true },
    });
  }

  public async findAssignmentById(id: string, user?: ActiveUserData) {
    const assignment = await this.estateAssignementRepository.findOne({
      where: { id },
      relations: { estate: { owner: true }, employee: true },
    });

    if (!assignment) throw new NotFoundException('assignment not found');

    if (
      user &&
      user.role === AuthRole.OWNER &&
      assignment.estate?.owner?.id !== user.ownerId
    ) {
      throw new ForbiddenException('You do not have access to this assignment');
    }

    return assignment;
  }

  public async removeAssignment(id: string, user?: ActiveUserData) {
    const assignment = await this.findAssignmentById(id, user);

    await this.estateAssignementRepository.remove(assignment);
    return { message: 'assignment deleted successfully' };
  }
}

import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { CreateEstateDto } from '../dtos/createEstateDto';
import { UpdateEstateDto } from '../dtos/updateEstateDto';
import { Repository } from 'typeorm';
import { Estate } from '../estate.entity';
import { InjectRepository } from '@nestjs/typeorm';
import { Crop } from 'src/crop/crop.entity';
import { Owner } from 'src/owners/owner.entity';
import { Role } from 'src/auth/enums/role.enum';
import { EstateStatus } from '../enums/estate-status.enum';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class EstatesService {
  constructor(
    @InjectRepository(Estate)
    private readonly estatesRepository: Repository<Estate>,

    @InjectRepository(Crop)
    private readonly cropRepository: Repository<Crop>,

    @InjectRepository(Owner)
    private readonly ownerRepository: Repository<Owner>,
  ) {}

  public async findAll(user?: ActiveUserData) {
    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      return this.estatesRepository.find({
        where: { owner: { id: user.ownerId } },
        relations: { owner: true, crop: true },
      });
    }

    return this.estatesRepository.find({
      relations: { owner: true, crop: true },
    });
  }

  public async findOne(id: string, user?: ActiveUserData) {
    const estate = await this.estatesRepository.findOne({
      where: { id },
      relations: { owner: true, crop: true },
    });

    if (!estate) {
      throw new NotFoundException(`Estate with ID ${id} not found`);
    }

    if (user && user.role === Role.OWNER && estate.owner?.id !== user.ownerId) {
      throw new ForbiddenException('You do not have access to this estate');
    }

    return estate;
  }

  public async createEstate(
    createEstateDto: CreateEstateDto,
    user?: ActiveUserData,
  ) {
    const cropId = createEstateDto.cropId ?? createEstateDto.crop;
    const requestedOwnerId = createEstateDto.ownerId ?? createEstateDto.owner;

    let ownerId = requestedOwnerId;

    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      if (requestedOwnerId && requestedOwnerId !== user.ownerId) {
        throw new ForbiddenException(
          'You can only create estates under your own owner account',
        );
      }
      ownerId = user.ownerId;
    }

    if (!cropId || !ownerId) {
      throw new BadRequestException('Both crop and owner IDs are required');
    }

    const existingCode = await this.estatesRepository.findOne({
      where: { code: createEstateDto.code },
    });
    if (existingCode) {
      throw new ConflictException('An estate with this code already exists');
    }

    const [crop, owner] = await Promise.all([
      this.cropRepository.findOne({ where: { id: cropId } }),
      this.ownerRepository.findOne({ where: { id: ownerId } }),
    ]);

    if (!crop) throw new NotFoundException('Crop not found');
    if (!owner) throw new NotFoundException('Owner not found');

    // Automatically set estate status as active for owner upon registration
    const status =
      user && user.role === Role.OWNER
        ? EstateStatus.ACTIVE
        : (createEstateDto.status ?? EstateStatus.ACTIVE);

    const estate = this.estatesRepository.create({
      owner,
      crop,
      name: createEstateDto.name,
      code: createEstateDto.code,
      location: createEstateDto.location,
      boundary: createEstateDto.boundary,
      status,
    });

    return this.estatesRepository.save(estate);
  }

  public async updateEstate(
    id: string,
    updateEstateDto: UpdateEstateDto,
    user?: ActiveUserData,
  ) {
    const estate = await this.findOne(id, user);

    const cropId = updateEstateDto.cropId ?? updateEstateDto.crop;
    if (cropId) {
      const crop = await this.cropRepository.findOne({ where: { id: cropId } });
      if (!crop) throw new NotFoundException('Crop not found');
      estate.crop = crop;
    }

    const ownerId = updateEstateDto.ownerId ?? updateEstateDto.owner;
    if (ownerId) {
      if (user && user.role === Role.OWNER && ownerId !== user.ownerId) {
        throw new ForbiddenException(
          'You cannot transfer an estate to another owner',
        );
      }
      const owner = await this.ownerRepository.findOne({
        where: { id: ownerId },
      });
      if (!owner) throw new NotFoundException('Owner not found');
      estate.owner = owner;
    }

    if (updateEstateDto.name !== undefined) {
      estate.name = updateEstateDto.name;
    }
    if (updateEstateDto.code !== undefined) {
      estate.code = updateEstateDto.code;
    }
    if (updateEstateDto.location !== undefined) {
      estate.location = updateEstateDto.location;
    }
    if (updateEstateDto.boundary !== undefined) {
      estate.boundary = updateEstateDto.boundary;
    }
    if (updateEstateDto.status !== undefined) {
      estate.status = updateEstateDto.status;
    }

    return this.estatesRepository.save(estate);
  }

  public async deleteEstate(id: string, user?: ActiveUserData) {
    const estate = await this.findOne(id, user);
    try {
      await this.estatesRepository.query(
        'DELETE FROM "estate_assignment" WHERE "estate_id" = $1',
        [estate.id],
      );
      await this.estatesRepository.query(
        'DELETE FROM "worker_assignment" WHERE "estate_id" = $1',
        [estate.id],
      );
    } catch {
      // Safe catch
    }
    await this.estatesRepository.remove(estate);
    return { message: 'Estate deleted successfully' };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { InjectRepository } from '@nestjs/typeorm';
import { IsNull, Repository } from 'typeorm';
import { WorkerIotReading } from '../entities/worker-iot-reading.entity';
import { EnvironmentIotReading } from '../entities/environment-iot-reading.entity';
import { Device } from '../entities/device.entity';
import { DeviceAssignment } from '../entities/device-assignment.entity';
import { Employee } from 'src/employees/employee.entity';
import { Estate } from 'src/estates/estate.entity';
import { WorkSession } from 'src/work-sessions/work-session.entity';
import { ConfigureIotCloudDto } from '../dtos/configure-iot-cloud.dto';

export interface CloudWorkerReadingPayload {
  rawMessage?: string;
  deviceCode?: string;
  deviceId?: string;
  workerId?: string;
  estateId?: string;
  workSessionId?: string;
  recordedAt?: string;
  location?: {
    latitude: number;
    longitude: number;
  };
  activityStatus?: string;
}

export interface CloudEnvReadingPayload {
  deviceCode?: string;
  deviceId?: string;
  estateId?: string;
  recordedAt?: string;
  temperature?: number;
  humidity?: number;
  soilMoisture?: number;
  location?: {
    latitude: number;
    longitude: number;
  };
}

@Injectable()
export class IotCloudFetchService {
  private readonly logger = new Logger(IotCloudFetchService.name);

  private apiUrl: string;
  private apiKey: string;
  private workerReadingsPath: string;
  private environmentReadingsPath: string;
  private isEnabled: boolean;

  constructor(
    private readonly configService: ConfigService,
    @InjectRepository(WorkerIotReading)
    private readonly workerReadingsRepo: Repository<WorkerIotReading>,
    @InjectRepository(EnvironmentIotReading)
    private readonly envReadingsRepo: Repository<EnvironmentIotReading>,
    @InjectRepository(Device)
    private readonly devicesRepo: Repository<Device>,
    @InjectRepository(DeviceAssignment)
    private readonly assignmentsRepo: Repository<DeviceAssignment>,
    @InjectRepository(Employee)
    private readonly employeesRepo: Repository<Employee>,
    @InjectRepository(Estate)
    private readonly estatesRepo: Repository<Estate>,
    @InjectRepository(WorkSession)
    private readonly workSessionsRepo: Repository<WorkSession>,
  ) {
    this.apiUrl =
      this.configService.get<string>('IOT_CLOUD_API_URL') ??
      'https://api.estate360-cloud.com';
    this.apiKey = this.configService.get<string>('IOT_CLOUD_API_KEY') ?? '';
    this.workerReadingsPath =
      this.configService.get<string>('IOT_CLOUD_WORKER_PATH') ??
      '/readings/workers';
    this.environmentReadingsPath =
      this.configService.get<string>('IOT_CLOUD_ENV_PATH') ??
      '/readings/environment';
    this.isEnabled =
      this.configService.get<string>('IOT_CLOUD_FETCH_ENABLED') !== 'false';
  }

  public getConfig() {
    return {
      apiUrl: this.apiUrl,
      apiKeyConfigured: Boolean(this.apiKey),
      workerReadingsPath: this.workerReadingsPath,
      environmentReadingsPath: this.environmentReadingsPath,
      enabled: this.isEnabled,
      fullWorkerUrl: `${this.apiUrl}${this.workerReadingsPath}`,
      fullEnvUrl: `${this.apiUrl}${this.environmentReadingsPath}`,
    };
  }

  public updateConfig(newConfig: ConfigureIotCloudDto) {
    if (newConfig.apiUrl !== undefined) {
      this.apiUrl = newConfig.apiUrl.replace(/\/+$/, '');
    }
    if (newConfig.apiKey !== undefined) {
      this.apiKey = newConfig.apiKey;
    }
    if (newConfig.workerReadingsPath !== undefined) {
      this.workerReadingsPath = newConfig.workerReadingsPath.startsWith('/')
        ? newConfig.workerReadingsPath
        : `/${newConfig.workerReadingsPath}`;
    }
    if (newConfig.environmentReadingsPath !== undefined) {
      this.environmentReadingsPath =
        newConfig.environmentReadingsPath.startsWith('/')
          ? newConfig.environmentReadingsPath
          : `/${newConfig.environmentReadingsPath}`;
    }
    if (newConfig.enabled !== undefined) {
      this.isEnabled = newConfig.enabled;
    }

    this.logger.log(`IoT Cloud Fetch configuration updated: ${this.apiUrl}`);
    return this.getConfig();
  }

  /**
   * Parses LoRa string format from worker_device.ino:
   * WORKER|<DEVICE_UUID>|LAT=6.927100|LON=79.861200|ALT=12.50|STATUS=ACTIVE
   */
  public parseRawLoRaWorkerPacket(
    raw: string,
  ): CloudWorkerReadingPayload | null {
    const parts = raw.trim().split('|');
    if (parts.length < 3 || parts[0] !== 'WORKER') {
      return null;
    }

    const deviceIdentifier = parts[1];
    let lat: number | undefined;
    let lon: number | undefined;
    let activityStatus = 'UNKNOWN';

    for (let i = 2; i < parts.length; i++) {
      const [key, val] = parts[i].split('=');
      if (key === 'LAT' && val && val !== 'INVALID') {
        const parsed = parseFloat(val);
        if (!Number.isNaN(parsed)) lat = parsed;
      } else if (key === 'LON' && val && val !== 'INVALID') {
        const parsed = parseFloat(val);
        if (!Number.isNaN(parsed)) lon = parsed;
      } else if (key === 'STATUS' && val) {
        activityStatus = val;
      }
    }

    return {
      deviceId: deviceIdentifier,
      deviceCode: deviceIdentifier,
      activityStatus,
      location:
        lat !== undefined && lon !== undefined
          ? { latitude: lat, longitude: lon }
          : undefined,
    };
  }

  public async fetchAndSyncWorkerReadings(filter?: {
    estateId?: string;
    limit?: number;
  }) {
    if (!this.isEnabled) {
      return { status: 'skipped', message: 'Cloud IoT fetching is disabled' };
    }

    const query = new URLSearchParams();
    if (filter?.estateId) query.set('estateId', filter.estateId);
    if (filter?.limit) query.set('limit', String(filter.limit));

    const url = `${this.apiUrl}${this.workerReadingsPath}${query.toString() ? `?${query.toString()}` : ''}`;
    this.logger.log(`Fetching worker readings from: ${url}`);

    try {
      const response = await fetch(url, {
        headers: {
          Authorization: `Bearer ${this.apiKey}`,
          'X-API-KEY': this.apiKey,
          Accept: 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(
          `Cloud server responded with status: ${response.status} ${response.statusText}`,
        );
      }

      const data = (await response.json()) as Array<
        CloudWorkerReadingPayload | string
      >;
      const normalizedItems: CloudWorkerReadingPayload[] = [];

      if (Array.isArray(data)) {
        for (const entry of data) {
          if (typeof entry === 'string') {
            const parsed = this.parseRawLoRaWorkerPacket(entry);
            if (parsed) normalizedItems.push(parsed);
          } else if (entry && typeof entry === 'object') {
            if (entry.rawMessage) {
              const parsed = this.parseRawLoRaWorkerPacket(entry.rawMessage);
              if (parsed) normalizedItems.push({ ...parsed, ...entry });
            } else {
              normalizedItems.push(entry);
            }
          }
        }
      }

      const synced = await this.saveWorkerReadings(normalizedItems);

      return {
        status: 'success',
        syncedCount: synced.length,
        items: synced,
      };
    } catch (error: unknown) {
      const errorMessage =
        error instanceof Error
          ? error.message
          : 'Failed to fetch from cloud server';
      this.logger.error(`Error fetching worker readings: ${errorMessage}`);
      return {
        status: 'error',
        message: errorMessage,
      };
    }
  }

  public async fetchAndSyncEnvironmentReadings(filter?: {
    estateId?: string;
    limit?: number;
  }) {
    if (!this.isEnabled) {
      return { status: 'skipped', message: 'Cloud IoT fetching is disabled' };
    }

    const query = new URLSearchParams();
    if (filter?.estateId) query.set('estateId', filter.estateId);
    if (filter?.limit) query.set('limit', String(filter.limit));

    const url = `${this.apiUrl}${this.environmentReadingsPath}${query.toString() ? `?${query.toString()}` : ''}`;
    this.logger.log(`Fetching environment readings from: ${url}`);

    try {
      const response = await fetch(url, {
        headers: {
          Authorization: `Bearer ${this.apiKey}`,
          'X-API-KEY': this.apiKey,
          Accept: 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(
          `Cloud server responded with status: ${response.status} ${response.statusText}`,
        );
      }

      const data = (await response.json()) as CloudEnvReadingPayload[];
      const synced = await this.saveEnvReadings(
        Array.isArray(data) ? data : [],
      );

      return {
        status: 'success',
        syncedCount: synced.length,
        items: synced,
      };
    } catch (error: unknown) {
      const errorMessage =
        error instanceof Error
          ? error.message
          : 'Failed to fetch from cloud server';
      this.logger.error(`Error fetching environment readings: ${errorMessage}`);
      return {
        status: 'error',
        message: errorMessage,
      };
    }
  }

  public async syncAll(filter?: { estateId?: string; limit?: number }) {
    const [workerResult, envResult] = await Promise.all([
      this.fetchAndSyncWorkerReadings(filter),
      this.fetchAndSyncEnvironmentReadings(filter),
    ]);

    return {
      timestamp: new Date().toISOString(),
      workerReadings: workerResult,
      environmentReadings: envResult,
    };
  }

  public async saveWorkerReadings(items: CloudWorkerReadingPayload[]) {
    const savedRecords: WorkerIotReading[] = [];

    for (const item of items) {
      let device: Device | null = null;
      if (item.deviceId) {
        device = await this.devicesRepo
          .findOne({ where: { id: item.deviceId } })
          .catch(() => null);
      }
      if (!device && (item.deviceCode || item.deviceId)) {
        device = await this.devicesRepo.findOne({
          where: { deviceCode: item.deviceCode ?? item.deviceId },
        });
      }

      if (!device) continue;

      let worker = item.workerId
        ? await this.employeesRepo.findOne({ where: { id: item.workerId } })
        : null;
      let estate = item.estateId
        ? await this.estatesRepo.findOne({ where: { id: item.estateId } })
        : null;

      // Auto-resolve worker and estate from active DeviceAssignment if not provided in payload
      if (!worker || !estate) {
        const activeAssignment = await this.assignmentsRepo.findOne({
          where: { device: { id: device.id }, endDate: IsNull() },
          relations: { worker: true, estate: true },
        });
        if (activeAssignment) {
          worker = worker ?? activeAssignment.worker ?? null;
          estate = estate ?? activeAssignment.estate ?? null;
        }
      }

      if (!worker || !estate) continue;

      let workSession = item.workSessionId
        ? await this.workSessionsRepo.findOne({
            where: { id: item.workSessionId },
          })
        : null;

      if (!workSession) {
        workSession = await this.workSessionsRepo.findOne({
          where: {
            worker: { id: worker.id },
            estate: { id: estate.id },
            status: 'active',
          },
        });
      }

      const reading = this.workerReadingsRepo.create({
        device,
        worker,
        estate,
        workSession: workSession ?? null,
        recordedAt: item.recordedAt ? new Date(item.recordedAt) : new Date(),
        activityStatus: item.activityStatus ?? 'active',
        location: item.location
          ? {
              type: 'Point',
              coordinates: [item.location.longitude, item.location.latitude],
            }
          : undefined,
      });

      const saved = await this.workerReadingsRepo.save(reading);
      savedRecords.push(saved);
    }

    return savedRecords;
  }

  public async saveEnvReadings(items: CloudEnvReadingPayload[]) {
    const savedRecords: EnvironmentIotReading[] = [];

    for (const item of items) {
      let device: Device | null = null;
      if (item.deviceId) {
        device = await this.devicesRepo
          .findOne({ where: { id: item.deviceId } })
          .catch(() => null);
      }
      if (!device && (item.deviceCode || item.deviceId)) {
        device = await this.devicesRepo.findOne({
          where: { deviceCode: item.deviceCode ?? item.deviceId },
        });
      }

      if (!device) continue;

      let estate = item.estateId
        ? await this.estatesRepo.findOne({ where: { id: item.estateId } })
        : null;

      if (!estate) {
        const activeAssignment = await this.assignmentsRepo.findOne({
          where: { device: { id: device.id }, endDate: IsNull() },
          relations: { estate: true },
        });
        if (activeAssignment) {
          estate = activeAssignment.estate;
        }
      }

      if (device && estate) {
        const reading = this.envReadingsRepo.create({
          device,
          estate,
          recordedAt: item.recordedAt ? new Date(item.recordedAt) : new Date(),
          temperature: item.temperature,
          humidity: item.humidity,
          soilMoisture: item.soilMoisture,
          location: item.location
            ? {
                type: 'Point',
                coordinates: [item.location.longitude, item.location.latitude],
              }
            : undefined,
        });

        const saved = await this.envReadingsRepo.save(reading);
        savedRecords.push(saved);
      }
    }

    return savedRecords;
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Device } from '../entities/device.entity';
import { DeviceAssignment } from '../entities/device-assignment.entity';
import { WorkerIotReading } from '../entities/worker-iot-reading.entity';
import { EnvironmentIotReading } from '../entities/environment-iot-reading.entity';
import { CreateDeviceDto } from '../dtos/create-device.dto';
import { CreateDeviceAssignmentDto } from '../dtos/create-device-assignment.dto';
import { CreateWorkerReadingDto } from '../dtos/create-worker-reading.dto';
import { CreateEnvironmentReadingDto } from '../dtos/create-environment-reading.dto';
import { Employee } from 'src/employees/employee.entity';
import { Estate } from 'src/estates/estate.entity';
import { WorkSession } from 'src/work-sessions/work-session.entity';
import { Role } from 'src/auth/enums/role.enum';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class IotService {
  constructor(
    @InjectRepository(Device)
    private readonly devicesRepository: Repository<Device>,

    @InjectRepository(DeviceAssignment)
    private readonly assignmentsRepository: Repository<DeviceAssignment>,

    @InjectRepository(WorkerIotReading)
    private readonly workerReadingsRepository: Repository<WorkerIotReading>,

    @InjectRepository(EnvironmentIotReading)
    private readonly envReadingsRepository: Repository<EnvironmentIotReading>,

    @InjectRepository(Employee)
    private readonly employeesRepository: Repository<Employee>,

    @InjectRepository(Estate)
    private readonly estatesRepository: Repository<Estate>,

    @InjectRepository(WorkSession)
    private readonly workSessionsRepository: Repository<WorkSession>,
  ) {}

  public async verifyEstateOwnership(estateId: string, user?: ActiveUserData) {
    const estate = await this.estatesRepository.findOne({
      where: { id: estateId },
      relations: { owner: true },
    });
    if (!estate) {
      throw new NotFoundException('Estate not found');
    }
    if (user && user.role === Role.OWNER && estate.owner?.id !== user.ownerId) {
      throw new ForbiddenException('You do not have access to this estate');
    }
    return estate;
  }

  public async createDevice(createDto: CreateDeviceDto) {
    const device = this.devicesRepository.create(createDto);
    return this.devicesRepository.save(device);
  }

  public async findAllDevices(user?: ActiveUserData) {
    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      return this.devicesRepository
        .createQueryBuilder('device')
        .innerJoin('device.assignments', 'assignment')
        .innerJoin('assignment.estate', 'estate')
        .where('estate.owner_id = :ownerId', { ownerId: user.ownerId })
        .distinct(true)
        .getMany();
    }

    return this.devicesRepository.find();
  }

  public async findDeviceById(id: string, user?: ActiveUserData) {
    const device = await this.devicesRepository.findOne({
      where: { id },
      relations: { assignments: { estate: { owner: true } } },
    });
    if (!device) {
      throw new NotFoundException(`Device with ID ${id} not found`);
    }

    if (user && user.role === Role.OWNER) {
      const hasAccess = (device.assignments ?? []).some(
        (a) => a.estate?.owner?.id === user.ownerId,
      );
      if (!hasAccess) {
        throw new ForbiddenException('You do not have access to this device');
      }
    }

    return device;
  }

  public async createAssignment(
    createDto: CreateDeviceAssignmentDto,
    user?: ActiveUserData,
  ) {
    const [device, estate] = await Promise.all([
      this.devicesRepository.findOne({ where: { id: createDto.deviceId } }),
      this.estatesRepository.findOne({
        where: { id: createDto.estateId },
        relations: { owner: true },
      }),
    ]);

    if (!device) throw new NotFoundException('Device not found');
    if (!estate) throw new NotFoundException('Estate not found');

    if (user && user.role === Role.OWNER && estate.owner?.id !== user.ownerId) {
      throw new ForbiddenException(
        'You can only assign devices to your own estates',
      );
    }

    let worker: Employee | null = null;
    if (createDto.workerId) {
      worker = await this.employeesRepository.findOne({
        where: { id: createDto.workerId },
        relations: { owner: true },
      });
      if (!worker) throw new NotFoundException('Worker not found');

      if (
        user &&
        user.role === Role.OWNER &&
        worker.owner &&
        worker.owner.id !== user.ownerId
      ) {
        throw new ForbiddenException(
          'You cannot assign a device to another owner’s worker',
        );
      }
    }

    const assignment = this.assignmentsRepository.create({
      device,
      worker,
      estate,
      startDate: new Date(createDto.startDate),
      endDate: createDto.endDate ? new Date(createDto.endDate) : undefined,
    });

    return this.assignmentsRepository.save(assignment);
  }

  public async findAllAssignments(user?: ActiveUserData) {
    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      return this.assignmentsRepository.find({
        where: { estate: { owner: { id: user.ownerId } } },
        relations: { device: true, worker: true, estate: true },
      });
    }

    return this.assignmentsRepository.find({
      relations: { device: true, worker: true, estate: true },
    });
  }

  public async createWorkerReading(
    dto: CreateWorkerReadingDto,
    user?: ActiveUserData,
  ) {
    const [device, worker, estate, workSession] = await Promise.all([
      this.devicesRepository.findOne({ where: { id: dto.deviceId } }),
      this.employeesRepository.findOne({ where: { id: dto.workerId } }),
      this.estatesRepository.findOne({
        where: { id: dto.estateId },
        relations: { owner: true },
      }),
      this.workSessionsRepository.findOne({ where: { id: dto.workSessionId } }),
    ]);

    if (!device) throw new NotFoundException('Device not found');
    if (!worker) throw new NotFoundException('Worker not found');
    if (!estate) throw new NotFoundException('Estate not found');
    if (!workSession) throw new NotFoundException('WorkSession not found');

    if (user && user.role === Role.OWNER && estate.owner?.id !== user.ownerId) {
      throw new ForbiddenException(
        'You can only record readings for your own estates',
      );
    }

    const reading = this.workerReadingsRepository.create({
      device,
      worker,
      estate,
      workSession,
      recordedAt: dto.recordedAt ? new Date(dto.recordedAt) : new Date(),
      activityStatus: dto.activityStatus ?? 'active',
      location: dto.location
        ? {
            type: 'Point',
            coordinates: [dto.location.longitude, dto.location.latitude],
          }
        : undefined,
    });

    return this.workerReadingsRepository.save(reading);
  }

  public async findWorkerReadings(
    filter?: {
      estateId?: string;
      workerId?: string;
      sessionId?: string;
      limit?: number;
    },
    user?: ActiveUserData,
  ) {
    if (filter?.estateId && user?.role === Role.OWNER) {
      await this.verifyEstateOwnership(filter.estateId, user);
    }

    const query = this.workerReadingsRepository
      .createQueryBuilder('reading')
      .leftJoinAndSelect('reading.device', 'device')
      .leftJoinAndSelect('reading.worker', 'worker')
      .leftJoinAndSelect('reading.estate', 'estate')
      .leftJoinAndSelect('reading.workSession', 'workSession')
      .orderBy('reading.recordedAt', 'DESC')
      .take(filter?.limit ?? 50);

    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      query.andWhere('estate.owner_id = :ownerId', { ownerId: user.ownerId });
    }

    if (filter?.estateId) {
      query.andWhere('reading.estate_id = :estateId', {
        estateId: filter.estateId,
      });
    }
    if (filter?.workerId) {
      query.andWhere('reading.worker_id = :workerId', {
        workerId: filter.workerId,
      });
    }
    if (filter?.sessionId) {
      query.andWhere('reading.work_session_id = :sessionId', {
        sessionId: filter.sessionId,
      });
    }

    return query.getMany();
  }

  public async createEnvironmentReading(
    dto: CreateEnvironmentReadingDto,
    user?: ActiveUserData,
  ) {
    const [device, estate] = await Promise.all([
      this.devicesRepository.findOne({ where: { id: dto.deviceId } }),
      this.estatesRepository.findOne({
        where: { id: dto.estateId },
        relations: { owner: true },
      }),
    ]);

    if (!device) throw new NotFoundException('Device not found');
    if (!estate) throw new NotFoundException('Estate not found');

    if (user && user.role === Role.OWNER && estate.owner?.id !== user.ownerId) {
      throw new ForbiddenException(
        'You can only record readings for your own estates',
      );
    }

    const reading = this.envReadingsRepository.create({
      device,
      estate,
      recordedAt: new Date(dto.recordedAt),
      temperature: dto.temperature,
      humidity: dto.humidity,
      soilMoisture: dto.soilMoisture,
      location: dto.location
        ? {
            type: 'Point',
            coordinates: [dto.location.longitude, dto.location.latitude],
          }
        : undefined,
    });

    return this.envReadingsRepository.save(reading);
  }

  public async findEnvironmentReadings(
    filter?: {
      estateId?: string;
      deviceId?: string;
      limit?: number;
    },
    user?: ActiveUserData,
  ) {
    if (filter?.estateId && user?.role === Role.OWNER) {
      await this.verifyEstateOwnership(filter.estateId, user);
    }

    const query = this.envReadingsRepository
      .createQueryBuilder('reading')
      .leftJoinAndSelect('reading.device', 'device')
      .leftJoinAndSelect('reading.estate', 'estate')
      .orderBy('reading.recordedAt', 'DESC')
      .take(filter?.limit ?? 50);

    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      query.andWhere('estate.owner_id = :ownerId', { ownerId: user.ownerId });
    }

    if (filter?.estateId) {
      query.andWhere('reading.estate_id = :estateId', {
        estateId: filter.estateId,
      });
    }
    if (filter?.deviceId) {
      query.andWhere('reading.device_id = :deviceId', {
        deviceId: filter.deviceId,
      });
    }

    return query.getMany();
  }
}

import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
  OnModuleInit,
} from '@nestjs/common';
import { Repository } from 'typeorm';
import { Owner } from '../owner.entity';
import { InjectRepository } from '@nestjs/typeorm';
import { CreateOwnerDto } from '../dtos/createOwnerDto';
import { PatchOwnerDto } from '../dtos/patchOwnerDto';
import { User } from 'src/auth/entities/users.entity';
import { Role } from 'src/auth/enums/role.enum';
import { UserStatus } from 'src/auth/enums/user-status.enum';
import { BcryptService } from 'src/auth/providers/bcrypt.service';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class OwnersService implements OnModuleInit {
  constructor(
    @InjectRepository(Owner)
    private readonly ownersRepository: Repository<Owner>,

    @InjectRepository(User)
    private readonly usersRepository: Repository<User>,

    private readonly bcryptService: BcryptService,
  ) {}

  async onModuleInit() {
    try {
      await this.ownersRepository.query(`
        DO $$
        BEGIN
          IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='owner' AND column_name='contact_email') THEN
            UPDATE "owner" SET "email" = "contact_email" WHERE "email" IS NULL;
          END IF;
        END $$;
      `);
    } catch {
      // Safe catch
    }
  }

  public async createOwner(createOwnerDto: CreateOwnerDto) {
    const rawEmail = createOwnerDto.email ?? createOwnerDto.contactEmail;
    if (!rawEmail) {
      throw new BadRequestException('Owner email is required');
    }

    const normalizedEmail = rawEmail.trim().toLowerCase();

    const [existingUser, existingOwner] = await Promise.all([
      this.usersRepository.findOne({ where: { email: normalizedEmail } }),
      this.ownersRepository.findOne({ where: { email: normalizedEmail } }),
    ]);

    if (existingUser || existingOwner) {
      throw new ConflictException(
        'An owner or user with this email already exists',
      );
    }

    let owner = this.ownersRepository.create({
      name: createOwnerDto.name,
      email: normalizedEmail,
      phone: createOwnerDto.phone,
      address: createOwnerDto.address,
      status: createOwnerDto.status,
    });
    owner = await this.ownersRepository.save(owner);

    if (createOwnerDto.password) {
      const passwordHash = await this.bcryptService.hashPassword(
        createOwnerDto.password,
      );
      const user = this.usersRepository.create({
        email: normalizedEmail,
        passwordHash,
        role: Role.OWNER,
        status: UserStatus.ACTIVE,
        owner,
      });
      await this.usersRepository.save(user);
    }

    return owner;
  }

  public async findAllOwners() {
    return this.ownersRepository.find({
      relations: { estates: true },
    });
  }

  public async findOneOwner(id: string, user?: ActiveUserData) {
    if (user && user.role === Role.OWNER && user.ownerId !== id) {
      throw new ForbiddenException(
        'You can only access your own owner profile',
      );
    }

    const owner = await this.ownersRepository.findOne({
      where: { id },
      relations: { estates: true },
    });

    if (!owner) {
      throw new NotFoundException(`Owner with ID ${id} not found`);
    }

    return owner;
  }

  public async updateOwner(
    id: string,
    patchOwnerDto: PatchOwnerDto,
    user?: ActiveUserData,
  ) {
    const owner = await this.findOneOwner(id, user);

    if (patchOwnerDto.name !== undefined) {
      owner.name = patchOwnerDto.name;
    }

    const rawEmail = patchOwnerDto.email ?? patchOwnerDto.contactEmail;
    if (rawEmail !== undefined) {
      owner.email = rawEmail.trim().toLowerCase();
    }

    if (patchOwnerDto.phone !== undefined) {
      owner.phone = patchOwnerDto.phone;
    }
    if (patchOwnerDto.address !== undefined) {
      owner.address = patchOwnerDto.address;
    }
    if (patchOwnerDto.status !== undefined) {
      owner.status = patchOwnerDto.status;
    }

    if (patchOwnerDto.password) {
      const linkedUser = await this.usersRepository.findOne({
        where: { owner: { id } },
      });
      if (linkedUser) {
        linkedUser.passwordHash = await this.bcryptService.hashPassword(
          patchOwnerDto.password,
        );
        await this.usersRepository.save(linkedUser);
      }
    }

    return this.ownersRepository.save(owner);
  }

  public async deleteOwner(id: string) {
    const owner = await this.findOneOwner(id);
    await this.ownersRepository.remove(owner);
    return { message: 'Owner deleted successfully' };
  }
}

import {
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { EmployeePaymentDetail } from '../payment-details.entity';
import { CreatePaymentDetailDto } from '../dtos/createPaymentDetail.dto';
import { UpdatePaymentDetailDto } from '../dtos/updatePaymentDetail.dto';
import { Employee } from 'src/employees/employee.entity';
import { Role } from 'src/auth/enums/role.enum';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class PaymentDetailsService {
  constructor(
    @InjectRepository(EmployeePaymentDetail)
    private readonly paymentDetailsRepository: Repository<EmployeePaymentDetail>,

    @InjectRepository(Employee)
    private readonly employeesRepository: Repository<Employee>,
  ) {}

  private verifyEmployeeAccess(employee: Employee, user?: ActiveUserData) {
    if (!user || user.role !== Role.OWNER) {
      return;
    }

    if (!user.ownerId) {
      throw new ForbiddenException(
        'Owner profile is not linked to this account',
      );
    }

    const isDirectOwner = employee.owner?.id === user.ownerId;
    const isAssignedToOwnerEstate =
      (employee.estateAssignments ?? []).some(
        (ea) => ea.estate?.owner?.id === user.ownerId,
      ) ||
      (employee.workerAssignments ?? []).some(
        (wa) => wa.estate?.owner?.id === user.ownerId,
      );

    if (!isDirectOwner && !isAssignedToOwnerEstate) {
      throw new ForbiddenException(
        "You do not have access to this employee's payment details",
      );
    }
  }

  public async create(
    createDto: CreatePaymentDetailDto,
    user?: ActiveUserData,
  ) {
    const employee = await this.employeesRepository.findOne({
      where: { id: createDto.employeeId },
      relations: {
        owner: true,
        estateAssignments: { estate: { owner: true } },
        workerAssignments: { estate: { owner: true } },
      },
    });

    if (!employee) {
      throw new NotFoundException(
        `Employee with ID ${createDto.employeeId} not found`,
      );
    }

    this.verifyEmployeeAccess(employee, user);

    const existing = await this.paymentDetailsRepository.findOne({
      where: { employee: { id: createDto.employeeId } },
    });

    if (existing) {
      throw new ConflictException(
        'Payment details already exist for this employee',
      );
    }

    const paymentDetail = this.paymentDetailsRepository.create({
      employee,
      paymentFrequency: createDto.paymentFrequency,
      bankName: createDto.bankName,
      accountNumber: createDto.accountNumber,
      accountName: createDto.accountName,
      branch: createDto.branch,
      isActive: createDto.isActive ?? true,
    });

    return this.paymentDetailsRepository.save(paymentDetail);
  }

  public async findAll(user?: ActiveUserData) {
    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }

      return this.paymentDetailsRepository
        .createQueryBuilder('detail')
        .leftJoinAndSelect('detail.employee', 'employee')
        .leftJoin('employee.estateAssignments', 'ea')
        .leftJoin('ea.estate', 'eaEstate')
        .leftJoin('employee.workerAssignments', 'wa')
        .leftJoin('wa.estate', 'waEstate')
        .where(
          '(employee.owner_id = :ownerId OR eaEstate.owner_id = :ownerId OR waEstate.owner_id = :ownerId)',
          { ownerId: user.ownerId },
        )
        .distinct(true)
        .getMany();
    }

    return this.paymentDetailsRepository.find({
      relations: { employee: true },
    });
  }

  public async findByEmployeeId(employeeId: string, user?: ActiveUserData) {
    const detail = await this.paymentDetailsRepository.findOne({
      where: { employee: { id: employeeId } },
      relations: {
        employee: {
          owner: true,
          estateAssignments: { estate: { owner: true } },
          workerAssignments: { estate: { owner: true } },
        },
      },
    });

    if (!detail) {
      throw new NotFoundException(
        `Payment details for employee ID ${employeeId} not found`,
      );
    }

    this.verifyEmployeeAccess(detail.employee, user);

    return detail;
  }

  public async update(
    id: string,
    updateDto: UpdatePaymentDetailDto,
    user?: ActiveUserData,
  ) {
    const detail = await this.paymentDetailsRepository.findOne({
      where: { id },
      relations: {
        employee: {
          owner: true,
          estateAssignments: { estate: { owner: true } },
          workerAssignments: { estate: { owner: true } },
        },
      },
    });

    if (!detail) {
      throw new NotFoundException(`Payment detail with ID ${id} not found`);
    }

    this.verifyEmployeeAccess(detail.employee, user);

    if (updateDto.paymentFrequency !== undefined) {
      detail.paymentFrequency = updateDto.paymentFrequency;
    }
    if (updateDto.bankName !== undefined) {
      detail.bankName = updateDto.bankName;
    }
    if (updateDto.accountNumber !== undefined) {
      detail.accountNumber = updateDto.accountNumber;
    }
    if (updateDto.accountName !== undefined) {
      detail.accountName = updateDto.accountName;
    }
    if (updateDto.branch !== undefined) {
      detail.branch = updateDto.branch;
    }
    if (updateDto.isActive !== undefined) {
      detail.isActive = updateDto.isActive;
    }

    return this.paymentDetailsRepository.save(detail);
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { EstatePayRate } from '../entities/estate-pay-rate.entity';
import { Payroll } from '../entities/payroll.entity';
import { PayrollItem } from '../entities/payroll-item.entity';
import { Payment } from '../entities/payment.entity';
import { CreatePayRateDto } from '../dtos/create-pay-rate.dto';
import { GeneratePayrollDto } from '../dtos/generate-payroll.dto';
import { CreatePaymentDto } from '../dtos/create-payment.dto';
import { Estate } from 'src/estates/estate.entity';
import { Owner } from 'src/owners/owner.entity';
import { Employee } from 'src/employees/employee.entity';
import { ProductionRecord } from 'src/production/production-record.entity';
import { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';
import { Role } from 'src/auth/enums/role.enum';

@Injectable()
export class PayrollService {
  constructor(
    @InjectRepository(EstatePayRate)
    private readonly payRatesRepo: Repository<EstatePayRate>,

    @InjectRepository(Payroll)
    private readonly payrollRepo: Repository<Payroll>,

    @InjectRepository(PayrollItem)
    private readonly payrollItemRepo: Repository<PayrollItem>,

    @InjectRepository(Payment)
    private readonly paymentRepo: Repository<Payment>,

    @InjectRepository(Estate)
    private readonly estatesRepo: Repository<Estate>,

    @InjectRepository(Owner)
    private readonly ownersRepo: Repository<Owner>,

    @InjectRepository(Employee)
    private readonly employeesRepo: Repository<Employee>,

    @InjectRepository(ProductionRecord)
    private readonly productionRepo: Repository<ProductionRecord>,
  ) {}

  // Pay Rates
  public async createPayRate(dto: CreatePayRateDto, user?: ActiveUserData) {
    const estate = await this.estatesRepo.findOne({
      where: { id: dto.estateId },
      relations: { owner: true },
    });
    if (!estate) throw new NotFoundException('Estate not found');

    if (user?.role === Role.OWNER) {
      if (!user.ownerId || estate.owner?.id !== user.ownerId) {
        throw new ForbiddenException(
          'You do not have access to configure pay rates for this estate',
        );
      }
    }

    const payRate = this.payRatesRepo.create({
      estate,
      rate: dto.rate,
      unit: dto.unit,
      paymentFactor: dto.paymentFactor,
      effectiveFrom: new Date(dto.effectiveFrom),
      effectiveTo: dto.effectiveTo ? new Date(dto.effectiveTo) : undefined,
    });

    return this.payRatesRepo.save(payRate);
  }

  public async findPayRatesByEstate(estateId: string, user?: ActiveUserData) {
    const estate = await this.estatesRepo.findOne({
      where: { id: estateId },
      relations: { owner: true },
    });
    if (!estate) throw new NotFoundException('Estate not found');

    if (user?.role === Role.OWNER) {
      if (!user.ownerId || estate.owner?.id !== user.ownerId) {
        throw new ForbiddenException('You do not have access to this estate');
      }
    }

    return this.payRatesRepo.find({
      where: { estate: { id: estateId } },
      order: { effectiveFrom: 'DESC' },
    });
  }

  // Payroll Generation & Calculation
  public async generatePayroll(dto: GeneratePayrollDto, user?: ActiveUserData) {
    let targetOwnerId = dto.ownerId;

    if (user?.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile not linked to current user',
        );
      }
      if (targetOwnerId && targetOwnerId !== user.ownerId) {
        throw new ForbiddenException(
          'Owners can only generate payroll for their own estates',
        );
      }
      targetOwnerId = user.ownerId;
    }

    if (!targetOwnerId) {
      throw new BadRequestException('ownerId is required');
    }

    const owner = await this.ownersRepo.findOne({
      where: { id: targetOwnerId },
      relations: { estates: true },
    });
    if (!owner) throw new NotFoundException('Owner not found');

    const payroll = this.payrollRepo.create({
      owner,
      periodStart: new Date(dto.periodStart),
      periodEnd: new Date(dto.periodEnd),
      paymentFrequency: dto.paymentFrequency,
      status: 'draft',
    });
    const savedPayroll = await this.payrollRepo.save(payroll);

    // Calculate payroll items across owner's estates
    const estateIds = (owner.estates ?? []).map((e) => e.id);
    const payrollItems: PayrollItem[] = [];

    if (estateIds.length > 0) {
      // Find workers and production records in this period
      const productionRecords = await this.productionRepo
        .createQueryBuilder('p')
        .leftJoinAndSelect('p.worker', 'worker')
        .leftJoinAndSelect('p.estate', 'estate')
        .where('p.estate_id IN (:...estateIds)', { estateIds })
        .andWhere('p.created_at >= :start AND p.created_at <= :end', {
          start: new Date(dto.periodStart),
          end: new Date(dto.periodEnd),
        })
        .getMany();

      // Group production by worker and estate
      const map = new Map<
        string,
        { worker: Employee; estate: Estate; totalQuantity: number }
      >();
      for (const rec of productionRecords) {
        const key = `${rec.worker.id}_${rec.estate.id}`;
        if (!map.has(key)) {
          map.set(key, {
            worker: rec.worker,
            estate: rec.estate,
            totalQuantity: 0,
          });
        }
        map.get(key)!.totalQuantity += Number(rec.quantity);
      }

      for (const entry of map.values()) {
        const latestRate = await this.payRatesRepo.findOne({
          where: { estate: { id: entry.estate.id } },
          order: { effectiveFrom: 'DESC' },
        });

        const rate = latestRate ? Number(latestRate.rate) : 10;
        const factor = latestRate ? Number(latestRate.paymentFactor) : 1;
        const productionPay = entry.totalQuantity * rate * factor;
        const basicPay = 500; // standard baseline
        const grossPay = basicPay + productionPay;
        const deductions = Math.round(grossPay * 0.08 * 100) / 100; // e.g. 8% EPF
        const netPay = grossPay - deductions;

        const item = this.payrollItemRepo.create({
          payroll: savedPayroll,
          worker: entry.worker,
          estate: entry.estate,
          basicPay,
          productionPay,
          overtime: 0,
          allowances: 0,
          bonuses: 0,
          grossPay,
          deductions,
          netPay,
        });

        const savedItem = await this.payrollItemRepo.save(item);
        payrollItems.push(savedItem);
      }
    }

    savedPayroll.items = payrollItems;
    return savedPayroll;
  }

  public async findPayrolls(ownerId?: string, user?: ActiveUserData) {
    const query = this.payrollRepo
      .createQueryBuilder('payroll')
      .leftJoinAndSelect('payroll.owner', 'owner')
      .leftJoinAndSelect('payroll.items', 'items')
      .leftJoinAndSelect('items.worker', 'worker')
      .leftJoinAndSelect('items.estate', 'estate')
      .orderBy('payroll.createdAt', 'DESC');

    if (user?.role === Role.OWNER) {
      if (!user.ownerId) return [];
      if (ownerId && ownerId !== user.ownerId) {
        throw new ForbiddenException(
          'You do not have access to another owner payrolls',
        );
      }
      query.andWhere('payroll.owner_id = :ownerId', { ownerId: user.ownerId });
    } else if (ownerId) {
      query.andWhere('payroll.owner_id = :ownerId', { ownerId });
    }

    return query.getMany();
  }

  public async findPayrollById(id: string, user?: ActiveUserData) {
    const payroll = await this.payrollRepo.findOne({
      where: { id },
      relations: {
        owner: true,
        items: { worker: true, estate: true, payment: true },
      },
    });
    if (!payroll) throw new NotFoundException('Payroll not found');

    if (user?.role === Role.OWNER) {
      if (!user.ownerId || payroll.owner?.id !== user.ownerId) {
        throw new ForbiddenException('You do not have access to this payroll');
      }
    }

    return payroll;
  }

  public async processPayroll(id: string, user?: ActiveUserData) {
    const payroll = await this.findPayrollById(id, user);
    payroll.status = 'processed';
    payroll.processedAt = new Date();
    return this.payrollRepo.save(payroll);
  }

  // Payments
  public async createPayment(dto: CreatePaymentDto, user?: ActiveUserData) {
    const item = await this.payrollItemRepo.findOne({
      where: { id: dto.payrollItemId },
      relations: {
        payment: true,
        estate: { owner: true },
        payroll: { owner: true },
      },
    });
    if (!item) throw new NotFoundException('Payroll item not found');

    if (user?.role === Role.OWNER) {
      const itemOwnerId = item.estate?.owner?.id ?? item.payroll?.owner?.id;
      if (!user.ownerId || itemOwnerId !== user.ownerId) {
        throw new ForbiddenException(
          'You do not have access to create a payment for this payroll item',
        );
      }
    }

    const payment = this.paymentRepo.create({
      payrollItem: item,
      amount: dto.amount,
      paymentDate: new Date(dto.paymentDate),
      bankName: dto.bankName,
      accountNumber: dto.accountNumber,
      accountName: dto.accountName,
      transactionReference: dto.transactionReference,
      status: dto.status ?? 'completed',
    });

    return this.paymentRepo.save(payment);
  }

  public async findPayments(user?: ActiveUserData) {
    if (user?.role === Role.OWNER) {
      if (!user.ownerId) return [];
      return this.paymentRepo.find({
        where: { payrollItem: { estate: { owner: { id: user.ownerId } } } },
        relations: { payrollItem: { worker: true, estate: true } },
      });
    }

    return this.paymentRepo.find({
      relations: { payrollItem: { worker: true, estate: true } },
    });
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { ProductionRecord } from '../production-record.entity';
import { CreateProductionRecordDto } from '../dtos/create-production-record.dto';
import { Employee } from 'src/employees/employee.entity';
import { Estate } from 'src/estates/estate.entity';
import { WorkSession } from 'src/work-sessions/work-session.entity';
import { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';
import { Role } from 'src/auth/enums/role.enum';

@Injectable()
export class ProductionService {
  constructor(
    @InjectRepository(ProductionRecord)
    private readonly productionRepo: Repository<ProductionRecord>,

    @InjectRepository(Employee)
    private readonly employeesRepo: Repository<Employee>,

    @InjectRepository(Estate)
    private readonly estatesRepo: Repository<Estate>,

    @InjectRepository(WorkSession)
    private readonly sessionsRepo: Repository<WorkSession>,
  ) {}

  public async create(dto: CreateProductionRecordDto, user?: ActiveUserData) {
    const [worker, estate, workSession] = await Promise.all([
      this.employeesRepo.findOne({
        where: { id: dto.workerId },
        relations: { owner: true },
      }),
      this.estatesRepo.findOne({
        where: { id: dto.estateId },
        relations: { owner: true },
      }),
      this.sessionsRepo.findOne({
        where: { id: dto.workSessionId },
        relations: { estate: { owner: true } },
      }),
    ]);

    if (!worker) throw new NotFoundException('Worker not found');
    if (!estate) throw new NotFoundException('Estate not found');
    if (!workSession) throw new NotFoundException('Work session not found');

    if (user?.role === Role.OWNER) {
      if (!user.ownerId || estate.owner?.id !== user.ownerId) {
        throw new ForbiddenException(
          'You do not have access to record production for this estate',
        );
      }
      if (worker.owner && worker.owner.id !== user.ownerId) {
        throw new ForbiddenException('You do not have access to this worker');
      }
      if (workSession.estate?.owner?.id !== user.ownerId) {
        throw new ForbiddenException(
          'You do not have access to this work session',
        );
      }
    }

    const record = this.productionRepo.create({
      worker,
      estate,
      workSession,
      quantity: dto.quantity,
      unit: dto.unit,
      recordedAt: dto.recordedAt ? new Date(dto.recordedAt) : new Date(),
    });

    return this.productionRepo.save(record);
  }

  public async findAll(
    filter?: {
      workerId?: string;
      estateId?: string;
      workSessionId?: string;
    },
    user?: ActiveUserData,
  ) {
    const query = this.productionRepo
      .createQueryBuilder('production')
      .leftJoinAndSelect('production.worker', 'worker')
      .leftJoinAndSelect('production.estate', 'estate')
      .leftJoinAndSelect('production.workSession', 'workSession')
      .orderBy('production.createdAt', 'DESC');

    if (user?.role === Role.OWNER) {
      if (!user.ownerId) return [];
      query.andWhere('estate.owner_id = :ownerId', { ownerId: user.ownerId });
    }

    if (filter?.workerId) {
      query.andWhere('production.worker_id = :workerId', {
        workerId: filter.workerId,
      });
    }
    if (filter?.estateId) {
      query.andWhere('production.estate_id = :estateId', {
        estateId: filter.estateId,
      });
    }
    if (filter?.workSessionId) {
      query.andWhere('production.work_session_id = :workSessionId', {
        workSessionId: filter.workSessionId,
      });
    }

    return query.getMany();
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
  OnModuleInit,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { WorkerAssignment } from '../entities/worker-assignment.entity';
import { Estate } from 'src/estates/estate.entity';
import { Employee } from 'src/employees/employee.entity';
import { CreateWorkerAssignmentDto } from '../dtos/worker-assignment/createWorkerAssignmentDto';
import { UpdateWorkerAssignmentDto } from '../dtos/worker-assignment/updateWorkerAssignmentDto';
import { Role as AuthRole } from 'src/auth/enums/role.enum';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class WorkerAssignmentService implements OnModuleInit {
  constructor(
    @InjectRepository(WorkerAssignment)
    private readonly workerAssignmentRepository: Repository<WorkerAssignment>,

    @InjectRepository(Estate)
    private readonly estateRepository: Repository<Estate>,

    @InjectRepository(Employee)
    private readonly employeeRepository: Repository<Employee>,
  ) {}

  async onModuleInit() {
    try {
      await this.workerAssignmentRepository.query(`
        DO $$
        BEGIN
          IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='worker_assignment' AND column_name='employee_id') THEN
            UPDATE "worker_assignment" SET "worker_id" = "employee_id" WHERE "worker_id" IS NULL;
          END IF;
        END $$;
      `);
    } catch {
      // Safe catch
    }
  }

  public async createAssignment(
    dto: CreateWorkerAssignmentDto,
    user?: ActiveUserData,
  ) {
    const estate = await this.estateRepository.findOne({
      where: { id: dto.estateId },
      relations: { owner: true },
    });

    if (!estate) {
      throw new NotFoundException('Estate not found');
    }

    if (
      user &&
      user.role === AuthRole.OWNER &&
      estate.owner?.id !== user.ownerId
    ) {
      throw new ForbiddenException(
        'You can only assign workers to your own estates',
      );
    }

    const worker = await this.employeeRepository.findOne({
      where: { id: dto.workerId },
      relations: { owner: true },
    });

    if (!worker) {
      throw new NotFoundException('Employee not found');
    }

    if (
      user &&
      user.role === AuthRole.OWNER &&
      worker.owner &&
      worker.owner.id !== user.ownerId
    ) {
      throw new ForbiddenException(
        'You cannot assign a worker belonging to another owner',
      );
    }

    let supervisor: Employee | null = null;
    const supervisorId = dto.supervisorId ?? dto.superVisorId;

    if (supervisorId) {
      supervisor = await this.employeeRepository.findOne({
        where: { id: supervisorId },
        relations: { owner: true },
      });

      if (!supervisor) {
        throw new NotFoundException('Supervisor not found');
      }

      if (
        user &&
        user.role === AuthRole.OWNER &&
        supervisor.owner &&
        supervisor.owner.id !== user.ownerId
      ) {
        throw new ForbiddenException(
          'You cannot assign a supervisor belonging to another owner',
        );
      }
    }

    const assignment = this.workerAssignmentRepository.create({
      estate,
      worker,
      supervisor,
      startDate: dto.startDate,
      endDate: dto.endDate,
    });

    return this.workerAssignmentRepository.save(assignment);
  }

  public async updateAssignment(
    id: string,
    dto: UpdateWorkerAssignmentDto,
    user?: ActiveUserData,
  ) {
    const assignment = await this.findAssignmentById(id, user);

    if (dto.estateId !== undefined) {
      const estate = await this.estateRepository.findOne({
        where: { id: dto.estateId },
        relations: { owner: true },
      });

      if (!estate) {
        throw new NotFoundException('Estate not found');
      }

      if (
        user &&
        user.role === AuthRole.OWNER &&
        estate.owner?.id !== user.ownerId
      ) {
        throw new ForbiddenException(
          'You can only assign workers to your own estates',
        );
      }

      assignment.estate = estate;
    }

    if (dto.workerId !== undefined) {
      const worker = await this.employeeRepository.findOne({
        where: { id: dto.workerId },
        relations: { owner: true },
      });

      if (!worker) {
        throw new NotFoundException('Employee not found');
      }

      if (
        user &&
        user.role === AuthRole.OWNER &&
        worker.owner &&
        worker.owner.id !== user.ownerId
      ) {
        throw new ForbiddenException(
          'You cannot assign a worker belonging to another owner',
        );
      }

      assignment.worker = worker;
    }

    const updatedSupervisorId =
      dto.supervisorId !== undefined ? dto.supervisorId : dto.superVisorId;

    if (updatedSupervisorId !== undefined) {
      if (updatedSupervisorId === null) {
        assignment.supervisor = null;
      } else {
        const supervisor = await this.employeeRepository.findOne({
          where: { id: updatedSupervisorId },
          relations: { owner: true },
        });

        if (!supervisor) {
          throw new NotFoundException('Supervisor not found');
        }

        if (
          user &&
          user.role === AuthRole.OWNER &&
          supervisor.owner &&
          supervisor.owner.id !== user.ownerId
        ) {
          throw new ForbiddenException(
            'You cannot assign a supervisor belonging to another owner',
          );
        }

        assignment.supervisor = supervisor;
      }
    }

    if (dto.startDate !== undefined) {
      assignment.startDate = dto.startDate;
    }

    if (dto.endDate !== undefined) {
      assignment.endDate = dto.endDate;
    }

    return this.workerAssignmentRepository.save(assignment);
  }

  public async findAllAssignments(user?: ActiveUserData) {
    if (user && user.role === AuthRole.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      return this.workerAssignmentRepository.find({
        where: { estate: { owner: { id: user.ownerId } } },
        relations: { estate: true, worker: true, supervisor: true },
      });
    }

    return this.workerAssignmentRepository.find({
      relations: { estate: true, worker: true, supervisor: true },
    });
  }

  public async findAssignmentById(id: string, user?: ActiveUserData) {
    const assignment = await this.workerAssignmentRepository.findOne({
      where: { id },
      relations: { estate: { owner: true }, worker: true, supervisor: true },
    });

    if (!assignment) throw new NotFoundException('assignment not found');

    if (
      user &&
      user.role === AuthRole.OWNER &&
      assignment.estate?.owner?.id !== user.ownerId
    ) {
      throw new ForbiddenException('You do not have access to this assignment');
    }

    return assignment;
  }

  public async deleteAssignment(id: string, user?: ActiveUserData) {
    const assignment = await this.findAssignmentById(id, user);

    await this.workerAssignmentRepository.remove(assignment);

    return { message: 'Worker assignment deleted successfully' };
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { WorkSession } from '../work-session.entity';
import {
  CreateWorkSessionDto,
  EndWorkSessionDto,
} from '../dtos/work-session.dto';
import { Employee } from 'src/employees/employee.entity';
import { Estate } from 'src/estates/estate.entity';
import { Role } from 'src/auth/enums/role.enum';
import type { ActiveUserData } from 'src/auth/interfaces/active-user-data.interface';

@Injectable()
export class WorkSessionsService {
  constructor(
    @InjectRepository(WorkSession)
    private readonly sessionsRepository: Repository<WorkSession>,

    @InjectRepository(Employee)
    private readonly employeesRepository: Repository<Employee>,

    @InjectRepository(Estate)
    private readonly estatesRepository: Repository<Estate>,
  ) {}

  public async startSession(
    createDto: CreateWorkSessionDto,
    user?: ActiveUserData,
  ) {
    const [worker, estate] = await Promise.all([
      this.employeesRepository.findOne({
        where: { id: createDto.workerId },
        relations: { owner: true },
      }),
      this.estatesRepository.findOne({
        where: { id: createDto.estateId },
        relations: { owner: true },
      }),
    ]);

    if (!worker) throw new NotFoundException('Worker not found');
    if (!estate) throw new NotFoundException('Estate not found');

    if (user && user.role === Role.OWNER) {
      if (estate.owner?.id !== user.ownerId) {
        throw new ForbiddenException(
          'You can only start work sessions in your own estates',
        );
      }
      if (worker.owner && worker.owner.id !== user.ownerId) {
        throw new ForbiddenException(
          'You cannot start a session for another owner’s worker',
        );
      }
    }

    const session = this.sessionsRepository.create({
      worker,
      estate,
      startTime: createDto.startTime
        ? new Date(createDto.startTime)
        : new Date(),
      status: createDto.status ?? 'active',
    });

    return this.sessionsRepository.save(session);
  }

  public async endSession(
    id: string,
    endDto: EndWorkSessionDto,
    user?: ActiveUserData,
  ) {
    const session = await this.findOne(id, user);

    session.endTime = endDto.endTime ? new Date(endDto.endTime) : new Date();
    session.status = endDto.status ?? 'completed';

    return this.sessionsRepository.save(session);
  }

  public async findAll(
    filter?: {
      workerId?: string;
      estateId?: string;
      status?: string;
    },
    user?: ActiveUserData,
  ) {
    const query = this.sessionsRepository
      .createQueryBuilder('session')
      .leftJoinAndSelect('session.worker', 'worker')
      .leftJoinAndSelect('session.estate', 'estate')
      .orderBy('session.startTime', 'DESC');

    if (user && user.role === Role.OWNER) {
      if (!user.ownerId) {
        throw new ForbiddenException(
          'Owner profile is not linked to this account',
        );
      }
      query.andWhere('estate.owner_id = :ownerId', { ownerId: user.ownerId });
    }

    if (filter?.workerId) {
      query.andWhere('session.worker_id = :workerId', {
        workerId: filter.workerId,
      });
    }
    if (filter?.estateId) {
      query.andWhere('session.estate_id = :estateId', {
        estateId: filter.estateId,
      });
    }
    if (filter?.status) {
      query.andWhere('session.status = :status', { status: filter.status });
    }

    return query.getMany();
  }

  public async findOne(id: string, user?: ActiveUserData) {
    const session = await this.sessionsRepository.findOne({
      where: { id },
      relations: { worker: true, estate: { owner: true } },
    });
    if (!session) {
      throw new NotFoundException(`Work session with ID ${id} not found`);
    }

    if (
      user &&
      user.role === Role.OWNER &&
      session.estate?.owner?.id !== user.ownerId
    ) {
      throw new ForbiddenException(
        'You do not have access to this work session',
      );
    }

    return session;
  }
}

